def summarize(rows):
    totals = {}
    seen = {}
    for row in rows:
        status = row['status']
        if status not in ('posted', 'pending'):
            raise ValueError('invalid status')
        if status == 'pending':
            continue

        direction = row['direction']
        if direction not in ('credit', 'debit'):
